insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 1, 'E ouviu Jetro, sacerdote de Midiã, sogro de Moisés, todas as coisas que Deus havia feito com Moisés, e com Israel seu povo, e como o SENHOR havia tirado a Israel do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 2, 'E tomou Jetro, sogro de Moisés a Zípora a mulher de Moisés, depois que ele a enviou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 3, 'E a seus dois filhos; um se chamava Gérson, porque disse: Peregrino fui em terra alheia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 4, 'E o outro se chamava Eliézer, porque disse, O Deus de meu pai me ajudou, e me livrou da espada de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 5, 'E Jetro o sogro de Moisés, com seus filhos e sua mulher, chegou a Moisés no deserto, onde tinha o acampamento junto ao monte de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 6, 'E disse a Moisés: Eu teu sogro Jetro venho a ti, com tua mulher, e seus dois filhos com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 7, 'E Moisés saiu a receber a seu sogro, e inclinou-se, e beijou-o: e perguntaram-se um ao outro como estavam, e vieram à tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 8, 'E Moisés contou a seu sogro todas as coisas que o SENHOR havia feito a Faraó e aos egípcios por causa de Israel, e todo o trabalho que haviam passado no caminho, e como os havia livrado o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 9, 'E alegrou-se Jetro de todo o bem que o SENHOR havia feito a Israel, que o havia livrado da mão dos egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 10, 'E Jetro disse: Bendito seja o SENHOR, que vos livrou da mão dos egípcios, e da mão de Faraó, e que livrou ao povo da mão dos egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 11, 'Agora conheço que o SENHOR é maior que todos os deuses, até naquilo em que se vangloriavam contra o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 12, 'E tomou Jetro, sogro de Moisés, holocaustos e sacrifícios para Deus: e veio Arão e todos os anciãos de Israel a comer pão com o sogro de Moisés diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 13, 'E aconteceu que outro dia se sentou Moisés a julgar ao povo; e o povo esteve diante de Moisés desde a manhã até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 14, 'E vendo o sogro de Moisés tudo o que ele fazia com o povo, disse: Que é isto que fazes tu com o povo? por que te sentas tu sozinho, e todo o povo está diante de ti desde a manhã até à tarde?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 15, 'E Moisés respondeu a seu sogro: Porque o povo vem a mim para consultar a Deus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 16, 'Quando têm negócios, vem a mim; e eu julgo entre o um e o outro, e declaro as ordenanças de Deus e suas leis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 17, 'Então o sogro de Moisés lhe disse: Não fazes bem:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 18, 'Desfalecerás de todo, tu, e também este povo que está contigo; porque o negócio é demasiado pesado para ti; não poderás fazê-lo tu sozinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 19, 'Ouve agora minha voz; eu te aconselharei, e Deus será contigo. Está tu pelo povo diante de Deus, e traze tu os negócios a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 20, 'E ensina a eles as ordenanças e as leis, e mostra-lhes o caminho por onde andem, e o que hão de fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 21, 'Ademais busca dentre todo o povo homens de virtude, temerosos de Deus, homens de verdade, que odeiem a ganância; e constituirás a estes sobre eles líderes sobre mil, sobre cem, sobre cinquenta e sobre dez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 22, 'Os quais julgarão ao povo ao todo tempo; e será que todo negócio grave o trarão a ti, e eles julgarão todo negócio pequeno: alivia assim a carga de sobre ti, e eles a levarão contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 23, 'Se isto fizeres, e Deus te o mandar, tu poderás persistir, e todo este povo se irá também em paz a seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 24, 'E ouviu Moisés a voz de seu sogro, e fez tudo o que disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 25, 'E escolheu Moisés homens de virtude de todo Israel, e os pôs por chefes sobre o povo, líderes sobre mil, sobre cem, sobre cinquenta, e sobre dez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 26, 'E julgavam ao povo ao todo tempo; o negócio árduo traziam-no a Moisés, e eles julgavam todo negócio pequeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 18, 27, 'E despediu Moisés a seu sogro, e foi-se à sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 1, 'Ao mês terceiro da saída dos filhos de Israel da terra do Egito, naquele dia vieram ao deserto de Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 2, 'Porque partiram de Refidim, e chegaram ao deserto de Sinai, e assentaram no deserto; e acampou ali Israel diante do monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 3, 'E Moisés subiu a Deus; e o SENHOR o chamou desde o monte, dizendo: Assim dirás à casa de Jacó, e anunciarás aos filhos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 4, 'Vós vistes o que fiz aos egípcios, e como vos tomei sobre asas de águas, e vos trouxe a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 5, 'Agora pois, se deres ouvido à minha voz, e guardardes meu pacto, vós sereis meu especial tesouro sobre todos os povos; porque minha é toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 6, 'E vós sereis meu reino de sacerdotes, e gente santa. Estas são as palavras que dirás aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 7, 'Então veio Moisés, e chamou aos anciãos do povo, e propôs em presença deles todas estas palavras que o SENHOR lhe havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 8, 'E todo o povo respondeu em unidade, e disseram: Tudo o que o SENHOR disse faremos. E Moisés referiu as palavras do povo ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 9, 'E o SENHOR disse a Moisés: Eis que, eu venho a ti em uma nuvem espessa, para que o povo ouça enquanto eu falo contigo, e também para que te creiam para sempre. E Moisés anunciou as palavras do povo ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 10, 'E o SENHOR disse a Moisés: Vai ao povo, e santifica-os hoje e amanhã, e lavem suas roupas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 11, 'E estejam prontos para o dia terceiro, porque ao terceiro dia o SENHOR descerá, à vista de todo o povo, sobre o monte de Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 12, 'E assinalarás termo ao povo em derredor, dizendo: Guardai-vos, não subais ao monte, nem toqueis a seu termo: qualquer um que tocar o monte, certamente morrerá:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 13, 'Não lhe tocará mão, mas será apedrejado ou flechado; seja animal ou seja homem, não viverá. Em havendo soado longamente a trombeta, subirão ao monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 14, 'E desceu Moisés do monte ao povo, e santificou ao povo; e lavaram suas roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 15, 'E disse ao povo: Estai prontos para o terceiro dia; não chegueis a mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 16, 'E aconteceu ao terceiro dia quando veio a manhã, que vieram trovões e relâmpagos, e espessa nuvem sobre o monte, e som de trombeta muito forte; e estremeceu-se todo o povo que estava no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 17, 'E Moisés tirou do acampamento ao povo a receber a Deus; e puseram-se ao abaixo do monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 18, 'E todo o monte de Sinai fumegava, porque o SENHOR havia descido sobre ele em fogo: e a fumaça dele subia como a fumaça de um forno, e todo o monte se estremeceu em grande maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 19, 'E o som da trombeta ia fortalecendo-se em extremo: Moisés falava, e Deus lhe respondia em voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 20, 'E desceu o SENHOR sobre o monte de Sinai, sobre o cume do monte: e chamou o SENHOR a Moisés ao cume do monte, e Moisés subiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 21, 'E o SENHOR disse a Moisés: Desce, exige ao povo que não ultrapassem o termo para ver ao SENHOR, para que não caia multidão deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 22, 'E também os sacerdotes que se achegam ao SENHOR, se santifiquem, para que o SENHOR não faça neles dano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 23, 'E Moisés disse ao SENHOR: O povo não poderá subir ao monte de Sinai, porque tu nos hás exigiste dizendo: Assinala termos ao monte, e santifica-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 24, 'E o SENHOR lhe disse: Vai, desce, e subirás tu, e Arão contigo: mas os sacerdotes e o povo não ultrapassem o termo para subir ao SENHOR, para que não faça neles dano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 19, 25, 'Então Moisés desceu ao povo e falou com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 1, 'E falou Deus todas estas palavras, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 2, 'Eu sou o SENHOR teu Deus, que te tirei da terra do Egito, de casa de servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 3, 'Não terás deuses alheios diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 4, 'Não te farás imagem, nem nenhuma semelhança de coisa que esteja acima no céu, nem abaixo na terra, nem nas águas debaixo da terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 5, 'Não te inclinarás a elas, nem as honrarás; porque eu sou o SENHOR teu Deus, forte, zeloso, que visito a maldade dos pais sobre os filhos, sobre os terceiros e sobre os quartos, aos que me aborrecem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 6, 'E que faço misericórdia em milhares aos que me amam, e guardam meus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 7, 'Não tomarás o nome do SENHOR teu Deus em vão; porque não dará por inocente o SENHOR ao que tomar seu nome em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 8, 'Tu te lembrarás do dia do repouso, para santificá-lo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 9, 'Seis dias trabalharás, e farás toda tua obra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 10, 'Mas o sétimo dia será repouso para o SENHOR teu Deus: não faças nele obra alguma, tu, nem teu filho, nem tua filha, nem teu servo, nem tua criada, nem teu animal, nem teu estrangeiro que está dentro de tuas portas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 11, 'Porque em seis dias fez o SENHOR os céus e a terra, o mar e todas as coisas que neles há, e repousou no sétimo dia: portanto o SENHOR abençoou o dia do repouso e o santificou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 12, 'Honra a teu pai e a tua mãe, para que teus dias se alarguem na terra que o SENHOR teu Deus te dá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 13, 'Não cometerás homicídio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 14, 'Não cometerás adultério.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 15, 'Não furtarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 16, 'Não falarás contra teu próximo falso testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 17, 'Não cobiçarás a casa de teu próximo, não cobiçarás a mulher de teu próximo, nem seu servo, nem sua criada, nem seu boi, nem seu asno, nem coisa alguma de teu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 18, 'Todo o povo considerava as vozes, e as chamas, e o som da trombeta, e o monte que fumegava: e vendo-o o povo, tremeram, e puseram-se de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 19, 'E disseram a Moisés: Fala tu conosco, que nós ouviremos; mas não fale Deus conosco, para que não morramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 20, 'E Moisés respondeu ao povo: Não temais; que para provar-vos veio Deus, e para que seu temor esteja em vossa presença para que não pequeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 21, 'Então o povo se pôs de longe, e Moisés se chegou à escuridão na qual estava Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 22, 'E o SENHOR disse a Moisés: Assim dirás aos filhos de Israel: Vós vistes que falei desde o céu convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 23, 'Não façais comigo deuses de prata, nem deuses de ouro vos fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 24, 'Da terra farás altar para mim, e sacrificarás sobre ele teus holocaustos e tuas ofertas pacíficas, tuas ovelhas e tuas vacas: em qualquer lugar onde eu fizer que esteja a memória de meu nome, virei a ti, e te abençoarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 25, 'E se me fizeres altar de pedras, não as faças lavradas; porque se levantares teu buril sobre ele, tu o profanarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 20, 26, 'E não subirás por degraus a meu altar, para que tua nudez não seja junto a ele descoberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 1, 'E estas são as ordenanças que lhes proporás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 2, 'Se comprares servo hebreu, seis anos servirá; mas ao sétimo sairá livre de graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 3, 'Se entrou sozinho, sozinho sairá: se tinha mulher, sairá ele e sua mulher com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 4, 'Se seu amo lhe houver dado mulher, e ela lhe houver dado à luz filhos ou filhas, a mulher e seus filhos serão de seu amo, e ele sairá sozinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 5, 'E se o servo disser: Eu amo a meu senhor, a minha mulher e a meus filhos, não sairei livre:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 6, 'Então seu amo o fará chegar aos juízes, e o fará chegar à porta ou ao umbral; e seu amo lhe furará a orelha com ferramenta pontiaguda, e será seu servo para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 7, 'E quando alguém vender sua filha por serva, não sairá como costumam sair os servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 8, 'Se ela não agradar ao seu senhor, o qual não a tomou por esposa, permitirá a ela que se resgate, e ela não a poderá vender a povo estrangeiro, visto que não cumpriu seu compromisso com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 9, 'Mas se a houver desposado com seu filho, fará com ela segundo o costume das filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 10, 'Se tomar para si outra, não diminuirá seu alimento, nem sua porção de roupa, nem o direito conjugal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 11, 'E se nenhuma destas três coisas fizer, ela sairá de graça, e não terá que lhe pagar dinheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 12, 'O que ferir á alguém, fazendo-lhe assim morrer, ele morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 13, 'Mas o que não armou ciladas, mas sim que Deus o pôs em suas mãos, então eu te assinalarei lugar ao qual há de fugir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 14, 'Além disso, se alguém se ensoberbecer contra seu próximo, e o matar traiçoeiramente, de meu altar o tirarás para que morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 15, 'E o que ferir a seu pai ou a sua mãe, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 16, 'Também o que roubar uma pessoa, e a vender, ou se achar em suas mãos, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 17, 'Igualmente o que amaldiçoar a seu pai ou a sua mãe, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 18, 'Ademais, se alguns brigarem, e algum ferir a seu próximo com pedra ou com o punho, e não morrer, mas cair em cama;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 19, 'Se se levantar e andar fora sobre seu cajado, então será o que lhe feriu absolvido: somente lhe pagará o tempo que esteve parado, e fará que lhe curem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 20, 'E se alguém ferir a seu servo ou a sua serva com pau, e morrer sob sua mão, será castigado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 21, 'Mas se durar por um dia ou dois, não será castigado, porque seu dinheiro é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 22, 'Se alguns brigarem, e ferissem a mulher grávida, e esta abortar, mas sem haver morte, será multado conforme o que lhe impuser o marido da mulher e julgarem os juízes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 23, 'Mas se houver morte, então pagarás vida por vida,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 24, 'Olho por olho, dente por dente, mão por meio, pé por pé,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 25, 'Queimadura por queimadura, ferida por ferida, golpe por golpe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 26, 'E quando alguém ferir o olho de seu servo, ou o olho de sua serva, e o destruir, lhe dará liberdade por razão de seu olho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 27, 'E se tirar o dente de seu servo, ou o dente de sua serva, por seu dente lhe deixará ir livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 28, 'Se um boi chifrar homem ou mulher, e de resultado morrer, o boi será apedrejado, e não se comerá sua carne; mas o dono do boi será absolvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 29, 'Porém se o boi era chifrador desde o passado, e a seu dono lhe foi feito advertência, e não o houver guardado, e matar homem ou mulher, o boi será apedrejado, e também morrerá seu dono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 30, 'Se lhe for imposto resgate, então dará pelo resgate de sua pessoa quanto lhe for imposto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 31, 'Quer tenha chifrado filho, ou tenha chifrado filha, conforme este juízo se fará com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 32, 'Se o boi chifrar servo ou serva, pagará trinta siclos de prata seu senhor, e o boi será apedrejado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 33, 'E se alguém abrir fosso, ou cavar cisterna, e não a cobrir, e cair ali boi ou asno,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 34, 'O dono da cisterna pagará o dinheiro, ressarcindo a seu dono, e o que foi morto será seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 35, 'E se o boi de alguém ferir ao boi de seu próximo, e este morrer, então venderão o boi vivo, e partirão o dinheiro dele, e também partirão o morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 21, 36, 'Mas se era notório que o boi era chifrador desde o passado, e seu dono não o houver guardado, pagará boi por boi, e o morto será seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 1, 'Quando alguém furtar boi ou ovelha, e lhe degolar ou vender, por aquele boi pagará cinco bois, e por aquela ovelha quatro ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 2, 'Se o ladrão for achado arrombando uma casa, e for ferido e morrer, o que lhe feriu não será culpado de sua morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 3, 'Se o sol houver sobre ele saído, o matador será réu de homicídio: o ladrão haverá de restituir completamente; se não tiver, será vendido por seu furto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 4, 'Se for achado com o furto na mão, seja boi ou asno ou ovelha vivos, pagará o dobro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 5, 'Se alguém fizer pastar campo ou vinha, e meter seu animal, e comer a terra de outro, do melhor de sua terra e do melhor de sua vinha pagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 6, 'Quando irromper um fogo, e achar espinhos, e for queimado amontoado, ou plantação, ou campo, o que acendeu o fogo pagará o queimado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 7, 'Quando alguém der a seu próximo prata ou joias a guardar, e for furtado da casa daquele homem, se o ladrão se achar, pagará o dobro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 8, 'Se o ladrão não se achar, então o dono da casa será apresentado aos juízes, para ver se pôs sua mão na riqueza de seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 9, 'Sobre todo negócio de fraude, sobre boi, sobre asno, sobre ovelha, sobre roupa, sobre toda coisa perdida, quando um disser: Isto é meu, a causa de ambos virá diante dos juízes; e o que os juízes condenarem, pagará o dobro a seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 10, 'Se alguém houver dado a seu próximo asno, ou boi, ou ovelha, ou qualquer outro animal a guardar, e se morrer ou se for aleijado, ou for levado sem vê-lo ninguém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 11, 'Juramento do SENHOR terá lugar entre ambos de que não lançou sua mão à riqueza de seu próximo: e seu dono o aceitará, e o outro não pagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 12, 'Mas se lhe houver sido furtado, ressarcirá a seu dono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 13, 'E se lhe houver sido arrebatado por fera, trará a ele testemunho, e não pagará o arrebatado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 14, 'Porém se alguém houver tomado emprestado animal de seu próximo, e for ferido ou morto, ausente seu dono, deverá pagá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 15, 'Se o dono estava presente, não o pagará. Se era alugado, ele virá por seu aluguel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 16, 'E se alguém enganar a alguma virgem que não for desposada, e dormir com ela, deverá pagar o dote por ela e tomá-la por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 17, 'Se seu pai não quiser dá-la a ele, ele lhe pesará prata conforme o dote das virgens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 18, 'À feiticeira não deixarás que viva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 19, 'Qualquer um que tiver ajuntamento com animal, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 20, 'O que sacrificar a deuses, exceto a somente o SENHOR, será morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 21, 'E ao estrangeiro não enganarás, nem angustiarás, porque estrangeiros fostes vós na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 22, 'A nenhuma viúva nem órfão afligireis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 23, 'Que se tu chegas a afligir-lhe, e ele a mim clamar, certamente ouvirei eu seu clamor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 24, 'E meu furor se acenderá, e vos matarei a espada, e vossas mulheres serão viúvas, e órfãos vossos filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 25, 'Se deres a meu povo dinheiro emprestado, ao pobre que está contigo, não te portarás com ele como agiota, nem lhe imporás juros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 26, 'Se tomares em penhor a roupa de teu próximo, a pôr do sol o devolverás a ele:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 27, 'Porque somente aquilo é sua coberta, é aquela a roupa para cobrir suas carnes, no que há de dormir: e será que quando ele a mim clamar, eu então lhe ouvirei, porque sou misericordioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 28, 'Não insultarás aos juízes, nem amaldiçoarás ao príncipe de teu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 29, 'Não adiarás as primícias de tua colheita, nem de teu licor, me darás o primogênito de teus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 30, 'Assim farás com o de teu boi e de tua ovelha: sete dias estará com sua mãe, e ao oitavo dia me o darás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 22, 31, 'E haveis de ser para mim homens santos: e não comereis carne arrebatada das feras no campo; aos cães a lançareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 1, 'Não admitirás falso rumor. Não serás cúmplice com o ímpio para ser falsa testemunha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 2, 'Não seguirás aos muitos para mal fazer; nem responderás em litigio inclinando-te à maioria para fazer injustiças;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 3, 'nem ao pobre privilegiarás em sua causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 4, 'Se encontrares o boi de teu inimigo ou seu asno extraviado, traze-o de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 5, 'Se vires o asno do que te aborrece caído debaixo de sua carga, lhe deixarás então desamparado? Sem falta ajudarás com ele a levantá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 6, 'Não perverterás o direito de teu pobre em seu pleito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 7, 'De palavra de mentira te afastarás, e não matarás ao inocente e justo; porque eu não justificarei ao ímpio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 8, 'Não receberás suborno; porque o suborno cega aos que veem, e perverte as palavras justas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 9, 'E não angustiarás ao estrangeiro: pois vós sabeis como se acha a alma do estrangeiro, já que estrangeiros fostes na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 10, 'Seis anos semearás tua terra, e recolherás sua colheita:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 11, 'Mas no sétimo a deixarás vazia e liberarás, para que comam os pobres de teu povo; e do que restar comerão os animais do campo; assim farás de tua vinha e de teu olival.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 12, 'Seis dias farás teus negócios, e ao sétimo dia folgarás, a fim que descanse teu boi e teu asno, e tome refrigério o filho de tua serva, e o estrangeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 13, 'E em tudo o que vos disse sereis avisados. E nome de outros deuses não mencionareis, nem se ouvirá de vossa boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 14, 'Três vezes no ano me celebrareis festa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 15, 'A festa dos pães ázimos guardarás: Sete dias comerás os pães sem levedura, como eu te mandei, no tempo do mês de Abibe; porque nele saíste do Egito: e ninguém comparecerá vazio diante de mim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 16, 'Também a festa da colheita, os primeiros frutos de teus trabalhos que houveres semeado no campo; e a festa da colheita à saída do ano, quando haverás recolhido teus trabalhos do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 17, 'Três vezes no ano comparecerá todo homem teu diante do Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 18, 'Não oferecerás com pão levedado o sangue de meu sacrifício, nem a gordura de meu animal sacrificado ficará da noite até a manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 19, 'As primícias dos primeiros frutos de tua terra trarás à casa do SENHOR teu Deus. Não cozerás o cabrito com o leite de sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 20, 'Eis que eu envio o anjo diante de ti para que te guarde no caminho, e te introduza no lugar que eu preparei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 21, 'Guarda-te diante dele, e ouve sua voz; não lhe sejas rebelde; porque ele não perdoará vossa rebelião: porque meu nome está nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 22, 'Porém se em verdade ouvires sua voz, e fizeres tudo o que eu te disser, serei inimigo a teus inimigos, e afligirei aos que te afligirem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 23, 'Porque meu anjo irá adiante de ti, e te introduzirá aos amorreus, e aos heteus, e aos perizeus, e aos cananeus, e aos heveus, e aos jebuseus, aos quais eu farei destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 24, 'Não te inclinarás a seus deuses, nem os servirás, nem farás como eles fazem; antes os destruirás por completo, e quebrarás inteiramente suas estátuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 25, 'Mas ao SENHOR vosso Deus servireis, e ele abençoará teu pão e tuas águas; e eu tirarei toda enfermidade do meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 26, 'Não haverá mulher que aborte, nem estéril em tua terra; e eu cumprirei o número de teus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 27, 'Eu enviarei meu terror diante de ti, e abaterei a todo povo onde tu entrares, e te darei o pescoço de todos os teus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 28, 'Eu enviarei a vespa diante de ti, que lance fora aos heveus, e aos cananeus, e aos heteus, de diante de ti:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 29, 'Não os expulsarei de diante de ti em ano, para que não fique a terra deserta, e se aumentem contra ti as feras do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 30, 'Pouco a pouco os expulsarei de diante de ti, até que te multipliques e tomes a terra por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 31, 'E eu porei teu termo desde o mar Vermelho até o mar de filístia, e desde o deserto até o rio: porque porei em vossas mãos os moradores da terra, e tu os expulsarás de diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 32, 'Não farás aliança com eles, nem com seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 23, 33, 'Em tua terra não habitarão, não seja que te façam pecar contra mim servindo a seus deuses: porque te será de tropeço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 1, 'E disse a Moisés: Sobe ao SENHOR, tu, e Arão, Nadabe, e Abiú, e setenta dos anciãos de Israel; e vos inclinareis desde longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 2, 'Mas Moisés somente se chegará ao SENHOR; e eles não se aproximem, nem suba com ele o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 3, 'E Moisés veio e contou ao povo todas as palavras do SENHOR, e todos os estatutos: e todo o povo respondeu em uma voz, e disseram: Executaremos todas as palavras que o SENHOR disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 4, 'E Moisés escreveu todas as palavras do SENHOR, e levantando-se de manhã edificou um altar ao pé do monte, e doze colunas, segundo as doze tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 5, 'E enviou aos rapazes dos filhos de Israel, os quais ofereceram holocaustos e sacrificaram pacíficos ao SENHOR, bezerros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 6, 'E Moisés tomou a metade do sangue, e a pôs em bacias, e espargiu a outra metade do sangue sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 7, 'E tomou o livro da aliança, e leu aos ouvidos do povo, o qual disse: Faremos todas as coisas que o SENHOR disse, e obedeceremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 8, 'Então Moisés tomou o sangue, e salpicou sobre o povo, e disse: Eis o sangue da aliança que o SENHOR fez convosco sobre todas estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 9, 'E subiram Moisés e Arão, Nadabe e Abiú, e setenta dos anciãos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 10, 'E viram ao Deus de Israel; e havia debaixo de seus pés como um pavimento de safira, semelhante ao céu quando está claro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 11, 'Mas não estendeu sua mão sobre os príncipes dos filhos de Israel: e viram a Deus, e comeram e beberam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 12, 'Então o SENHOR disse a Moisés: Sobe a mim ao monte, e espera ali, e te darei tábuas de pedra, e a lei, e mandamentos que escrevi para ensiná-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 13, 'E levantou-se Moisés, e Josué seu assistente; e Moisés subiu ao monte de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 14, 'E disse aos anciãos: Esperai-nos aqui até que voltemos a vós: e eis que Arão e Hur estão convosco: o que tiver negócios chegue-se a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 15, 'Então Moisés subiu ao monte, e uma nuvem cobriu o monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 16, 'E a glória do SENHOR repousou sobre o monte Sinai, e a nuvem o cobriu por seis dias: e ao sétimo dia chamou a Moisés do meio da nuvem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 17, 'E a aparência da glória do SENHOR era como um fogo abrasador no cume do monte, aos olhos dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 24, 18, 'E entrou Moisés em meio da nuvem, e subiu ao monte: e esteve Moisés no monte quarenta dias e quarenta noites.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 2, 'Dize aos filhos de Israel que tomem para mim oferta: de todo homem que a der de sua vontade, de coração, tomareis minha oferta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 3, 'E esta é a oferta que tomareis deles: Ouro, e prata, e bronze,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 4, 'E material azul, e púrpura, e carmesim, e linho fino, e pelo de cabras,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 5, 'E couros de carneiros tingidos de vermelho, e couros finos, e madeira de acácia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 6, 'Azeite para a luminária, especiarias para o azeite da unção, e para o incenso aromático;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 7, 'Pedras de ônix, e pedras de engastes, para o éfode, e para o peitoral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 8, 'E farão para mim um santuário, e eu habitarei entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 9, 'Conforme tudo o que eu te mostrar, o desenho do tabernáculo, e o desenho de todos os seus objetos, assim o fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 10, 'Farão também uma arca de madeira de acácia, cujo comprimento será de dois côvados e meio, e sua largura de côvado e meio, e sua altura de côvado e meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 11, 'E a cobrirás de ouro puro; por dentro e por fora a cobrirás; e farás sobre ela uma borda de ouro ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 12, 'E para ela farás de fundição quatro anéis de ouro, que porás a seus quatro cantos; dois anéis ao um lado dela, e dois anéis ao outro lado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 13, 'E farás umas varas de madeira de acácia, as quais cobrirás de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 14, 'E meterás as varas pelos anéis aos lados da arca, para levar a arca com elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 15, 'As varas se estarão nos anéis da arca: não se tirarão dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 16, 'E porás no arca o testemunho que eu te darei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 17, 'E farás uma coberta de ouro fino, cujo comprimento será de dois côvados e meio, e sua largura de côvado e meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 18, 'Farás também dois querubins de ouro, lavrados a martelo os farás, nas duas extremidades do propiciatório.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 19, 'Farás, pois, um querubim ao extremo de um lado, e um querubim ao outro extremo do lado oposto: da qualidade do propiciatório farás os querubins em suas duas extremidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 20, 'E os querubins estenderão por encima as asas, cobrindo com suas asas o propiciatório: suas faces a uma em frente da outra, olhando ao propiciatório as faces dos querubins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 21, 'E porás o propiciatório encima da arca, e no arca porás o testemunho que eu te darei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 22, 'E dali me declararei a ti, e falarei contigo de sobre o propiciatório, dentre os dois querubins que estão sobre a arca do testemunho, tudo o que eu te mandarei para os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 23, 'Farás também uma mesa de madeira de acácia: seu comprimento será de dois côvados, e de um côvado sua largura, e sua altura de côvado e meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 24, 'E a cobrirás de ouro puro, e lhe farás uma borda de ouro ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 25, 'Farás também para ele também uma moldura ao redor, da largura de uma mão, à qual moldura farás uma borda de ouro ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 26, 'E lhe farás quatro anéis de ouro, os quais porás aos quatro cantos que correspondem a seus quatro pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 27, 'Os anéis estarão antes da moldura, por lugares das varas, para levar a mesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 28, 'E farás as varas de madeira de acácia, e as cobrirás de ouro, e com elas será levada a mesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 29, 'Farás também seus pratos, e suas colheres, e seus jarros, e suas bacias, com que se fará libações: de ouro fino os farás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 30, 'E porás sobre a mesa o pão da proposição diante de mim continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 31, 'Farás também um candelabro de ouro puro; lavrado a martelo se fará o candelabro: seu pé, e sua cana, seus copos, seus botões, e suas flores, serão do mesmo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 32, 'E sairão seis braços de seus lados: três braços do candelabro do um lado seu, e três braços do candelabro do outro seu lado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 33, 'Três copos em forma de amêndoas em um braço, um botão e uma flor; e três copos, forma de amêndoas no outro braço, um botão e uma flor: assim, pois, nos seis braços que saem do candelabro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 34, 'E no candelabro quatro copos em forma de amêndoas, seus botões e suas flores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 35, 'Haverá um botão debaixo dos dois braços do mesmo, outro botão debaixo dos outros dois braços do mesmo, e outra botão debaixo dos outros dois braços do mesmo, em conformidade aos seis braços que saem do candelabro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 36, 'Seus botões e seus braços serão do mesmo, todo ele uma peça lavrada a martelo, de ouro puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 37, 'E farás para ele sete lâmpadas, as quais acenderás para que iluminem à parte de sua dianteira:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 38, 'Também suas tenazes e seus apagadores, de ouro puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 39, 'De um talento de ouro fino o farás, com todos estes objetos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 25, 40, 'E olha, e faze-os conforme seu modelo, que te foi mostrado no monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 1, 'E farás o tabernáculo de dez cortinas de linho torcido, azul, e púrpura, e carmesim: e farás querubins de obra delicada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 2, 'O comprimento da uma cortina de vinte e oito côvados, e a largura da mesma cortina de quatro côvados: todas as cortinas terão uma medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 3, 'Cinco cortinas estarão juntas a uma com a outra, e cinco cortinas unidas a uma com a outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 4, 'E farás laçadas de azul na beira da uma cortina, na margem, na juntura: e assim farás na beira da última cortina na juntura segunda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 5, 'Cinquenta laçadas farás na uma cortina, e cinquenta laçadas farás na margem da cortina que está na segunda juntura: as laçadas estarão contrapostas a uma à outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 6, 'Farás também cinquenta colchetes de ouro, com os quais juntarás as cortinas a uma com a outra, e se formará um tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 7, 'Farás também cortinas de pelo de cabras para uma tenda sobre o tabernáculo; onze cortinas farás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 8, 'O comprimento de uma cortina será de trinta côvados, e a largura da mesma cortina de quatro côvados: uma medida terão as onze cortinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 9, 'E juntarás as cinco cortinas à parte e as outras seis cortinas separadamente; e dobrarás a sexta cortina diante da face do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 10, 'E farás cinquenta laçadas na orla de uma cortina, à extremidade na juntura, e cinquenta laçadas na orla da segunda cortina na outra juntura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 11, 'Farás também cinquenta colchetes de alambre, os quais meterás pelas laçadas: e juntarás a tenda, para que se faça uma só cobertura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 12, 'E o excedente que resulta nas cortinas da tenda, a metade da uma cortina que sobra, ficará às costas do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 13, 'E um côvado da uma parte, e outro côvado da outra que sobra no comprimento das cortinas da tenda, pendurará sobre os lados do tabernáculo da uma parte e da outra, para cobri-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 14, 'Farás também à tenda uma coberta de couros de carneiros, tingidos de vermelho, e uma coberta de couros finos encima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 15, 'E farás para o tabernáculo tábuas de madeira de acácia, que estejam na vertical.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 16, 'O comprimento de cada tábua será de dez côvados, e de côvado e meio a largura de cada tábua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 17, 'Dois encaixes terá cada tábua, unidos um com o outro; assim farás todas as tábuas do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 18, 'Farás, pois, as tábuas do tabernáculo: vinte tábuas ao lado do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 19, 'E farás quarenta bases de prata debaixo das vinte tábuas; duas bases debaixo de uma tábua para seus dois encaixes, e duas bases debaixo da outra tábua para seus dois encaixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 20, 'E ao outro lado do tabernáculo, à parte do norte, vinte tábuas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 21, 'E suas quarenta bases de prata: duas bases debaixo de uma tábua, e duas bases debaixo da outra tábua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 22, 'E para o lado do tabernáculo, ao ocidente, farás seis tábuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 23, 'Farás também duas tábuas para as esquinas do tabernáculo nos dois ângulos posteriores;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 24, 'Os quais se unirão por abaixo, e também se juntarão por seu alto a uma argola: assim será das outras duas que estarão às duas esquinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 25, 'De maneira que serão oito tábuas, com suas bases de prata, dezesseis bases; duas bases debaixo de uma tábua, e duas bases debaixo da outra tábua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 26, 'Farás também cinco barras de madeira de acácia, para as tábuas de um lado do tabernáculo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 27, 'E cinco barras para as tábuas do outro lado do tabernáculo, e cinco barras para o outro lado do tabernáculo, que está ao ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 28, 'E a barra do meio passará por meio das tábuas, de uma extremidade à outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 29, 'E cobrirás as tábuas de ouro, e farás seus anéis de ouro para meter por eles as barras: também cobrirás as barras de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 30, 'E levantarás o tabernáculo conforme sua planta que te foi mostrada no monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 31, 'E farás também um véu de azul, e púrpura, e carmesim, e de linho torcido: será feito de primoroso trabalho, com querubins:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 32, 'E hás de pô-lo sobre quatro colunas de madeira de acácia cobertas de ouro; seus capitéis de ouro, sobre bases de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 33, 'E porás o véu debaixo dos colchetes, e meterás ali, do véu dentro, a arca do testemunho; e aquele véu vos fará separação entre o lugar santo e o santíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 34, 'E porás a coberta sobre a arca do testemunho no lugar santíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 35, 'E porás a mesa fora do véu, e o candelabro em frente da mesa ao lado do tabernáculo ao sul; e porás a mesa ao lado do norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 36, 'E farás à porta do tabernáculo uma cortina de azul, e púrpura, e carmesim, e linho torcido, obra de bordador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 26, 37, 'E farás para a cortina cinco colunas de madeira de acácia, as quais cobrirás de ouro, com seus capitéis de ouro: e as farás de fundição cinco bases de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 1, 'Farás também altar de madeira de acácia de cinco côvados de comprimento, e de cinco côvados de largura: será quadrado o altar, e sua altura de três côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 2, 'E farás suas pontas a seus quatro cantos; as pontas serão do mesmo; e as cobrirás de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 3, 'Farás também seus caldeirões para lançar sua cinza; e suas pás, e suas bacias, e seus garfos, e seus braseiros: farás todos os seus vasos de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 4, 'E lhe farás uma grelha de bronze de obra de malha; e sobre a grelha farás quatro anéis de bronze a seus quatro cantos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 5, 'E o porás dentro da borda do altar abaixo; e chegará a grelha até o meio do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 6, 'Farás também varas para o altar, varas de madeira de acácia, as quais cobrirás de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 7, 'E suas varas se meterão pelos anéis: e estarão aquelas varas a ambos lados do altar, quando houver de ser levado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 8, 'De tábuas o farás, oco: da maneira que te foi mostrado no monte, assim o farás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 9, 'Também farás o átrio do tabernáculo: ao lado do sul, terá o átrio cortinas de linho torcido, de cem côvados de comprimento cada um lado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 10, 'Suas vinte colunas, e suas vinte bases serão de bronze; os capitéis das colunas e suas molduras, de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 11, 'E da mesma maneira ao lado do norte haverá ao comprimento cortinas de cem côvados de comprimento, e suas vinte colunas, com suas vinte bases de bronze; os capitéis de suas colunas e suas molduras, de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 12, 'E a largura do átrio do lado ocidental terá cortinas de cinquenta côvados; suas colunas dez, com suas dez bases.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 13, 'E na largura do átrio pela parte do oriente, haverá cinquenta côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 14, 'E as cortinas de um lado serão de quinze côvados; suas colunas três, com suas três bases.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 15, 'Ao outro lado quinze côvados de cortinas; suas colunas três, com suas três bases.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 16, 'E à porta do átrio haverá uma cortina de vinte côvados, de azul, e púrpura, e carmesim, e linho torcido, de obra de bordador: suas colunas quatro, com suas quatro bases.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 17, 'Todas as colunas do átrio em derredor serão cingidas de prata; seus capitéis de prata, e suas bases de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 18, 'O comprimento do átrio será de cem côvados, e a largura cinquenta por um lado e cinquenta pelo outro, e a altura de cinco côvados: suas cortinas de linho torcido, e suas bases de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 19, 'Todos os utensílios do tabernáculo em todo o seu serviço, e todos os seus pregos, e todos os pregos do átrio, serão de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 20, 'E tu mandarás aos filhos de Israel que te tragam azeite puro de olivas, prensado, para a luminária, para fazer arder continuamente as lâmpadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 27, 21, 'No tabernáculo do testemunho, fora do véu que está diante do testemunho, as porá em ordem Arão e seus filhos, diante do SENHOR desde a tarde até a manhã, como estatuto perpétuo dos filhos de Israel por suas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 1, 'E tu aproxima a ti a Arão teu irmão, e a seus filhos consigo, dentre os filhos de Israel, para que sejam meus sacerdotes; a Arão, Nadabe e Abiú, Eleazar e Itamar, filhos de Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 2, 'E farás vestimentas sagradas a Arão teu irmão, para honra e formosura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 3, 'E tu falarás a todos os sábios de coração, aos quais eu enchi de espírito de sabedoria; a fim de que façam as roupas de Arão, para consagrar-lhe a que me sirva de sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 4, 'As vestimentas que farão são estes: o peitoral, e o éfode, e o manto, e a túnica bordada, a mitra, e o cinturão. Façam, pois, as sagradas vestimentas a Arão teu irmão, e a seus filhos, para que sejam meus sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 5, 'Tomarão ouro, e azul, e púrpura, e carmesim, e linho torcido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 6, 'E farão o éfode de ouro e azul, e púrpura, e carmesim, e linho torcido de obra de bordador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 7, 'Terá duas ombreiras que se juntem a seus dois lados, e se juntará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 8, 'E o artifício de seu cinto que está sobre ele, será de sua mesma obra, do mesmo; de ouro, azul, e púrpura, e carmesim, e linho torcido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 9, 'E tomarás duas pedras de ônix, e gravarás nelas os nomes dos filhos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 10, 'Os seis de seus nomes em uma pedra, e os outros seis nomes na outra pedra, conforme o nascimento deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 11, 'De obra de escultor em pedra a modo de gravuras de selo, farás gravar aquelas duas pedras com os nomes dos filhos de Israel; farás para eles ao redor engastes de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 12, 'E porás aquelas duas pedras sobre os ombros do éfode, para pedras de memória aos filhos de Israel; e Arão levará os nomes deles diante do SENHOR em seus dois ombros por memória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 13, 'Farás, pois, engastes de ouro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 14, 'E duas correntinhas de ouro fino; as quais farás de feitura de trança; e fixarás as correntes de feitura de trança nos engastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 15, 'Farás também o peitoral do juízo de primorosa obra, lhe farás conforme a obra do éfode, de ouro, e azul, e púrpura, e carmesim, e linho torcido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 16, 'Será quadrado e duplo, de um palmo de comprimento e um palmo de largura:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 17, 'E o encherás de pedrarias com quatro ordens de pedras: uma ordem de uma pedra sárdio, um topázio, e um carbúnculo; será a primeira ordem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 18, 'A segunda ordem, uma esmeralda, uma safira, e um diamante;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 19, 'A terceira ordem, um rubi, uma ágata, e uma ametista;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 20, 'E a quarta ordem, um berilo, um ônix, e um jaspe: estarão engastadas em ouro em seus encaixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 21, 'E serão aquelas pedra segundo os nomes dos filhos de Israel, doze segundo seus nomes; como gravuras de selo cada uma com seu nome, virão a ser segundo as doze tribos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 22, 'Farás também no peitoral correntes de feitura de tranças de ouro fino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 23, 'E farás no peitoral dois anéis de ouro, os quais dois anéis porás às duas pontas do peitoral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 24, 'E porás as duas tranças de ouro nos dois anéis às duas pontas do peitoral:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 25, 'E as duas extremidades das duas tranças sobre os dois engastes, e as porás aos lados do éfode na parte dianteira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 26, 'Farás também dois anéis de ouro, os quais porás às duas pontas do peitoral, em sua orla que está ao lado do éfode da parte de dentro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 27, 'Farás também dois anéis de ouro, os quais porás aos dois lados do éfode abaixo na parte dianteira, diante de sua juntura sobre o cinto do éfode.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 28, 'E juntarão o peitoral com seus anéis aos anéis do éfode com um cordão de azul, para que esteja sobre o cinto do éfode, e não se separe o peitoral do éfode.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 29, 'E levará Arão os nomes dos filhos de Israel no peitoral do juízo sobre seu coração, quando entrar no santuário, para memória diante do SENHOR continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 30, 'E porás no peitoral do juízo Urim e Tumim, para que estejam sobre o coração de Arão quando entrar diante do SENHOR: e levará sempre Arão o juízo dos filhos de Israel sobre seu coração diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 31, 'Farás o manto do éfode todo de material azul:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 32, 'E em meio dele por acima haverá uma abertura, a qual terá uma borda ao redor de obra de tecelão, como a abertura de um colarinho, para que não se rompa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 33, 'E abaixo em suas orlas farás romãs de material azul, e púrpura, e carmesim, por suas bordas ao redor; e entre elas sinos de ouro ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 34, 'Um sino de ouro e uma granada, sino de ouro e granada, pelas orlas do manto ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 35, 'E estará sobre Arão quando ministrar; e se ouvirá seu som quando ele entrar no santuário diante do SENHOR e quando sair, porque não morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 36, 'Farás também uma prancha de ouro fino, e gravarás nela gravura de selo, SANTIDADE AO SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 37, 'E a porás com um cordão de azul, e estará sobre a mitra; pela frente anterior da mitra estará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 38, 'E estará sobre a testa de Arão: e levará Arão o pecado das coisas santas, que os filhos de Israel houverem consagrado em todas as suas santas ofertas; e sobre sua testa estará continuamente para que tenham favor diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 39, 'E bordarás uma túnica de linho, e farás uma mitra de linho; farás também um cinto de obra de bordador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 40, 'E para os filhos de Arão farás túnicas; também lhes farás cintos, e lhes formarás tiaras para honra e adorno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 41, 'E com eles vestirás a Arão teu irmão, e a seus filhos com ele: e os ungirás, e os consagrarás, e santificarás, para que sejam meus sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 42, 'E lhes farás calções de linho para cobrir a carne vergonhosa; serão desde os lombos até as coxas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 28, 43, 'E estarão sobre Arão e sobre seus filhos quando entrarem no tabernáculo de testemunho, ou quando se achegarem ao altar para servir no santuário, para que não levem pecado, e morram. Estatuto perpétuo para ele, e para sua semente depois dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 1, 'E Isto é o que lhes farás para consagrá-los, para que sejam meus sacerdotes: Toma um bezerro das vacas, e dois carneiros sem mácula;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 2, 'E pães sem levedura, e tortas sem levedura amassadas com azeite, e massas sem levedura untadas com azeite; tu os farás de boa farinha de trigo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 3, 'E os porás em um cesto, e no cesto os oferecerás, com o bezerro e os dois carneiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 4, 'E farás chegar Arão e seus filhos à porta do tabernáculo do testemunho, e os lavarás com água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 5, 'E tomarás as vestiduras, e vestirás a Arão a túnica e o manto do éfode, e o éfode, e o peitoral, e lhe cingirás com o cinto do éfode;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 6, 'E porás a mitra sobre sua cabeça, e sobre a mitra porás a coroa santa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 7, 'E tomarás o azeite da unção, e derramarás sobre sua cabeça, e lhe ungirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 8, 'E farás chegar seus filhos, e lhes vestirás as túnicas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 9, 'E lhes cingirás o cinto, a Arão e a seus filhos, e lhes atarás as tiaras, e terão o sacerdócio por estatuto perpétuo: e encherás as mãos de Arão e de seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 10, 'E farás chegar o bezerro diante do tabernáculo do testemunho, e Arão e seus filhos porão suas mãos sobre a cabeça do bezerro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 11, 'E matarás o bezerro diante do SENHOR à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 12, 'E tomarás do sangue do bezerro, e porás sobre as pontas do altar com teu dedo, e derramarás todo o demais sangue ao pé do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 13, 'Tomarás também toda a gordura que cobre os intestinos, e o redenho de sobre o fígado, e os dois rins, e a gordura que está sobre eles, e os queimarás sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 14, 'Porém consumirás a fogo fora do acampamento a carne do bezerro, e seu couro, e seu excremento: é expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 15, 'Também tomarás um carneiro, e Arão e seus filhos porão suas mãos sobre a cabeça do carneiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 16, 'E matarás o carneiro, e tomarás seu sangue, e salpicarás sobre o altar ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 17, 'E cortarás o carneiro em pedaços, e lavarás seus intestinos e suas pernas, e as porás sobre seus pedaços e sobre sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 18, 'E queimarás todo o carneiro sobre o altar: é holocausto ao SENHOR, cheiro suave, é oferta queimada ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 19, 'Tomarás logo o outro carneiro, e Arão e seus filhos porão suas mãos sobre a cabeça do carneiro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 20, 'E matarás o carneiro, e tomarás de seu sangue, e porás sobre a ponta da orelha direita de Arão, e sobre a ponta das orelhas de seus filhos, e sobre o dedo polegar das mãos direitas deles, e sobre o dedo polegar dos pés direitos deles, e espargirás o sangue sobre o altar ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 21, 'E tomarás do sangue que há sobre o altar, e do azeite da unção, e espargirás sobre Arão, e sobre suas vestiduras, e sobre seus filhos, e sobre as vestimentas destes; e ele será santificado, e suas vestiduras, e seus filhos, e as vestimentas de seus filhos com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 22, 'Logo tomarás do carneiro a gordura, e a cauda, e a gordura que cobre os intestinos, e o redenho do fígado, e os dois rins, e a gordura que está sobre eles, e a coxa direita; porque é carneiro de consagrações:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 23, 'Também uma torta de pão, e uma massa amassada com azeite, e um bolo do cesto dos pães ázimos apresentado ao SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 24, 'E o porás tudo nas mãos de Arão, e nas mãos de seus filhos; e o mexerás agitando-o diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 25, 'Depois o tomarás de suas mãos, e o farás arder sobre o altar em holocausto, por cheiro agradável diante do SENHOR. É oferta acesa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 26, 'E tomarás o peito do carneiro das consagrações, que foi imolado para a de Arão, e o mexerás por oferta agitada diante do SENHOR; e será porção tua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 27, 'E separarás o peito da oferta mexida, e a coxa da santificação, o que foi mexido e o que foi santificado do carneiro das consagrações de Arão e de seus filhos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 28, 'E será para Arão e para seus filhos por estatuto perpétuo dos filhos de Israel, porque é porção elevada; e será tomada dos filhos de Israel de seus sacrifícios pacíficos, porção deles elevada em oferta ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 29, 'E as vestimentas santas, que são de Arão, serão de seus filhos depois dele, para ser ungidos com elas, e para ser com elas consagrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 30, 'Por sete dias as vestirá o sacerdote de seus filhos, que em seu lugar vier ao tabernáculo do testemunho a servir no santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 31, 'E tomarás o carneiro das consagrações, e cozerás sua carne no lugar do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 32, 'E Arão e seus filhos comerão a carne do carneiro, e o pão que está no cesto, à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 33, 'E comerão aquelas coisas com as quais se fez expiação, para encher suas mãos para ser santificados: mas o estrangeiro não comerá, porque é coisa santa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 34, 'E se sobrar algo da carne das consagrações e do pão até a manhã, queimarás ao fogo o que houver sobrado: não se comerá, porque é coisa santa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 35, 'Assim, pois, farás a Arão e a seus filhos, conforme todas as coisas que eu te mandei: por sete dias os consagrarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 36, 'E sacrificarás o bezerro da expiação em cada dia para as expiações; e purificarás o altar em havendo feito expiação por ele, e o ungirás para santificá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 37, 'Por sete dias expiarás o altar, e o santificarás, e será um altar santíssimo: qualquer um coisa que tocar ao altar, será santificada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 38, 'E isto é o que oferecerás sobre o altar: dois cordeiros de ano cada dia, sem interrupção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 39, 'Oferecerás um cordeiro à manhã, e o outro cordeiro oferecerás à queda da tarde:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 40, 'Também uma décima parte de um efa de boa farinha amassada com a quarta parte de um him de azeite prensado; e a libação será a quarta parte de um him de vinho com cada cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 41, 'E oferecerás o outro cordeiro à queda da tarde, fazendo conforme a oferta da manhã, e conforme sua libação, em cheiro de suavidade; será oferta acesa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 42, 'Isto será holocausto contínuo por vossas gerações à porta do tabernáculo do testemunho diante do SENHOR, no qual me encontrarei convosco, para falar-vos ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 43, 'E ali testificarei de mim aos filhos de Israel, e o lugar será santifiquei com minha glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 44, 'E santificarei o tabernáculo do testemunho e o altar: santificarei também a Arão e a seus filhos, para que sejam meus sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 45, 'E habitarei entre os filhos de Israel, e serei seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 29, 46, 'E conhecerão que eu sou o SENHOR seu Deus, que os tirei da terra do Egito, para habitar em meio deles: Eu sou o SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 1, 'Farás também um altar para queimar incenso: de madeira de acácia o farás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 2, 'Seu comprimento será de um côvado, e sua largura de um côvado: será quadrado: e sua altura de dois côvados: e suas pontas serão do mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 3, 'E o cobrirás de ouro puro, sua parte superior, e suas paredes em derredor, e suas pontas: e lhe farás em derredor uma coroa de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 4, 'Tu lhe farás também dois anéis de ouro debaixo de sua coroa a seus dois cantos em ambos lados seus, para meter as varas com que será levado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 5, 'E farás as varas de madeira de acácia, e os cobrirás de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 6, 'E o porás diante do véu que está junto à arca do testemunho, diante do propiciatório que está sobre o testemunho, onde eu te testificarei de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 7, 'E queimará sobre ele Arão incenso de aroma cada manhã quando preparar as lâmpadas o queimará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 8, 'E quando Arão acender as lâmpadas ao anoitecer, queimará o incenso: rito perpétuo diante do SENHOR por vossas idades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 9, 'Não oferecereis sobre ele incenso estranho, nem holocausto, nem oferta de cereais; nem tampouco derramareis libação sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 10, 'E sobre suas pontas fará Arão expiação uma vez no ano com o sangue da expiação para as reconciliações: uma vez no ano fará expiação sobre ele em vossas idades: será muito santo ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 11, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 12, 'Quando tomares o número dos filhos de Israel conforme a conta deles, cada um dará ao SENHOR o resgate de sua pessoa, quando os contares, e não haverá neles mortandade por havê-los contado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 13, 'Isto dará qualquer um que passar pela contagem, meio siclo conforme o siclo do santuário. O siclo é de vinte óbolos: a metade de um siclo será a oferta ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 14, 'Qualquer um que passar pela contagem, de vinte anos acima, dará a oferta ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 15, 'Nem o rico aumentará, nem o pobre diminuirá de meio siclo, quando derem a oferta ao SENHOR para fazer expiação por vossas pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 16, 'E tomarás dos filhos de Israel o dinheiro das expiações, e o darás para a obra do tabernáculo do testemunho: e será por memória aos filhos de Israel diante do SENHOR, para expiar vossas pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 17, 'Falou mais o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 18, 'Farás também uma pia de bronze, com sua base de bronze, para lavar; e a porás entre o tabernáculo do testemunho e o altar; e porás nela água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 19, 'E dela se lavarão Arão e seus filhos suas mãos e seus pés:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 20, 'Quando entrarem no tabernáculo do testemunho, se hão de lavar com água, e não morrerão: e quando se achegarem ao altar para ministrar, para acender ao SENHOR a oferta que se há de consumir ao fogo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 21, 'Também se lavarão as mãos e os pés, e não morrerão. E o terão por estatuto perpétuo ele e sua semente por suas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 22, 'Falou mais o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 23, 'E tu tomarás das principais especiarias; de mirra excelente quinhentos siclos, e de canela aromática a metade, isto é, duzentos e cinquenta, e de cálamo aromático duzentos e cinquenta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 24, 'E de cássia quinhentos, ao peso do santuário, e de azeite de olivas um him:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 25, 'E farás disso o azeite da santa unção, superior unguento, obra de perfumista, o qual será o azeite da unção sagrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 26, 'Com ele ungirás o tabernáculo do testemunho, e a arca do testemunho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 27, 'E a mesa, e todos os seus utensílios, e o candelabro, e todos os seus utensílios, e o altar do incenso,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 28, 'E o altar do holocausto, todos os seus utensílios, e a pia e sua base.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 29, 'Assim os consagrarás, e serão coisas santíssimas: tudo o que tocar neles, será santificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 30, 'Ungirás também a Arão e a seus filhos, e os consagrarás para que sejam meus sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 31, 'E falarás aos filhos de Israel, dizendo: Este será meu azeite da santa unção por vossas idades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 32, 'Sobre carne de homem não será untado, nem fareis outro semelhante, conforme sua composição: santo é; por santo haveis de tê-lo vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 33, 'Qualquer um que compuser unguento semelhante, e que puser dele sobre estranho, será cortado de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 34, 'Disse ainda o SENHOR a Moisés: Toma para ti aromas, resina de estoraque e um material odorífero e gálbano aromático e incenso limpo; de tudo em igual peso:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 35, 'E farás disso uma mistura aromática de obra de perfumista, bem misturada, pura e santa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 36, 'E moerás alguma dela pulverizando-a, e a porás diante do testemunho no tabernáculo do testemunho, onde eu te testificarei de mim. Isso vos será coisa santíssima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 37, 'Como a mistura que farás, não vos fareis outra segundo sua composição: te será coisa sagrada para o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 30, 38, 'Qualquer um que fizer outra como ela para cheirá-la, será cortado de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 2, 'Olha, eu chamei por seu nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 3, 'E o enchi de espírito de Deus, em sabedoria, e em inteligência, e em conhecimento, e em todo artifício,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 4, 'Para inventar desenhos, para trabalhar em ouro, e em prata, e em bronze,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 5, 'E em artifício de pedras para engastá-las, e em artifício de madeira; para agir em todo tipo de trabalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 6, 'E eis que eu pus com ele a Aoliabe, filho de Aisamaque, da tribo de Dã: e pus sabedoria no ânimo de todo sábio de coração, para que façam tudo o que te mandei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 7, 'O tabernáculo do testemunho, e a arca do testemunho, e o propiciatório que está sobre ela, e todos os utensílios do tabernáculo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 8, 'E a mesa e seus utensílios, e o candelabro limpo e todos os seus utensílios, e o altar do incenso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 9, 'E o altar do holocausto e todos os seus utensílios, e a pia e sua base;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 10, 'E as roupas do serviço, e as santas vestiduras para Arão o sacerdote, e as vestiduras de seus filhos, para que exerçam o sacerdócio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 11, 'E o azeite da unção, e o incenso aromático para o santuário: farão conforme tudo o que te mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 12, 'Falou também o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 13, 'E tu falarás aos filhos de Israel, dizendo: Com tudo isso vós guardareis meus sábados: porque é sinal entre mim e vós por vossas gerações, para que saibais que eu sou o SENHOR que vos santifico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 14, 'Assim guardareis o sábado, porque santo é a vós: o que o profanar, certamente morrerá; porque qualquer um que fizer obra alguma nele, aquela alma será cortada do meio de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 15, 'Seis dias se fará obra, mas o dia sétimo é sábado de repouso consagrado ao SENHOR; qualquer um que fizer obra no dia do sábado certamente morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 16, 'Guardarão, pois, o sábado os filhos de Israel: celebrando-o por suas gerações por pacto perpétuo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 17, 'Sinal é para sempre entre mim e os filhos de Israel; porque em seis dias fez o SENHOR os céus e a terra, e no sétimo dia cessou, e repousou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 31, 18, 'E deu a Moisés quando acabou de falar com ele no monte de Sinai, duas tábuas do testemunho, tábuas de pedra escritas com o dedo de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 1, 'Mas vendo o povo que Moisés tardava em descer do monte, achegou-se então a Arão, e disseram-lhe: Levanta-te, faze-nos deuses que vão adiante de nós; porque a este Moisés, aquele homem que tirou da terra do Egito, não sabemos o que lhe aconteceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 2, 'E Arão lhes disse: Separai os pendentes de ouro que estão nas orelhas de vossas mulheres, e de vossos filhos, e de vossas filhas, e trazei-os a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 3, 'Então todo o povo separou os pendentes de ouro que tinham em suas orelhas, e trouxeram-nos a Arão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 4, 'O qual os tomou das mãos deles, e formou-o com buril, e fez disso um bezerro de fundição. Então disseram: Israel, estes são teus deuses, que te tiraram da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 5, 'E vendo isto Arão, edificou um altar diante do bezerro; e apregoou Arão, e disse: Amanhã será festa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 6, 'E no dia seguinte madrugaram, e ofereceram holocaustos, e apresentaram pacíficos: e sentou-se o povo a comer e a beber, e levantaram-se a regozijar-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 7, 'Então o SENHOR disse a Moisés: Anda, desce, porque teu povo que tiraste da terra do Egito se corrompeu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 8, 'Logo se apartaram do caminho que eu lhes mandei, e se fizeram um bezerro de fundição, e o adoraram, e sacrificaram a ele, e disseram: Israel, estes são teus deuses, que te tiraram da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 9, 'Disse mais o SENHOR a Moisés: Eu vi a este povo, que por certo é povo de dura cerviz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 10, 'Agora, pois, deixa-me que se acenda meu furor neles, e os consuma: e a ti eu porei sobre grande gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 11, 'Então Moisés orou à face do SENHOR seu Deus, e disse: Ó SENHOR, por que se acenderá teu furor em teu povo, que tu tiraste da terra do Egito com grande força, e com mão forte?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 12, 'Por que hão de falar os egípcios, dizendo: Para o mal os tirou, para matá-los nos montes, e para exterminá-los de sobre a face da terra? Volta-te do furor de tua ira, e arrepende-te do mal de teu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 13, 'Lembra-te de Abraão, de Isaque, e de Israel teus servos, aos quais juraste por ti mesmo, e disse-lhes: Eu multiplicarei vossa semente como as estrelas do céu; e darei a vossa semente toda esta terra que disse, e a tomarão por herança para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 14, 'Então o SENHOR se arrependeu do mal que disse que havia de fazer a seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 15, 'E virou-se Moisés, e desceu do monte trazendo em sua mão as duas tábuas do testemunho, as tábuas escritas por ambos os lados; de uma parte e de outra estavam escritas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 16, 'E as tábuas eram obra de Deus, e a escritura era escritura de Deus gravada sobre as tábuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 17, 'E ouvindo Josué o clamor do povo que gritava, disse a Moisés: Barulho de batalha há no campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 18, 'E ele respondeu: Não é eco de gritos de vitória de fortes, nem eco de gritos de fracos: eu ouço barulho de cantorias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 19, 'E aconteceu, que quando chegou ele ao acampamento, e viu o bezerro e as danças, acendeu-se a ira a Moisés, e lançou as tábuas de suas mãos, e quebrou-as ao pé do monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 20, 'E tomou o bezerro que fizeram, e queimou-o no fogo, e moeu-o até reduzi-lo a pó, que espalhou sobre as águas, e deu-o a beber aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 21, 'E disse Moisés a Arão: Que te fez este povo, que trouxeste sobre ele tão grande pecado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 22, 'E respondeu Arão: Não se ire meu senhor; tu conheces o povo, que é inclinado ao mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 23, 'Porque me disseram: Faze-nos deuses que vão adiante de nós, que a este Moisés, o homem que tirou da terra do Egito, não sabemos o que lhe aconteceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 24, 'E eu lhes respondi: Quem tem ouro? Separai-o. E o deram a mim, e lancei-o no fogo, e saiu este bezerro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 25, 'E vendo Moisés que o povo estava descontrolado, porque Arão o havia deixado se descontrolarem para vergonha entre seus inimigos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 26, 'Pôs-se Moisés à porta do acampamento, e disse: Quem é do SENHOR? junte-se comigo. E juntaram-se com ele todos os filhos de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 27, 'E ele lhes disse: Assim disse o SENHOR, o Deus de Israel: Ponde cada um sua espada sobre sua coxa: passai e voltai de porta em porta pelo acampamento, e matai cada um a seu irmão, e a seu amigo, e a seu parente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 28, 'E os filhos de Levi o fizeram conforme o dito de Moisés: e caíram do povo naquele dia como três mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 29, 'Então Moisés disse: Hoje vos consagrastes ao SENHOR, porque cada um se consagrou em seu filho, e em seu irmão, para que dê ele hoje bênção sobre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 30, 'E aconteceu que no dia seguinte disse Moisés ao povo: Vós cometestes um grande pecado: mas eu subirei agora ao SENHOR; talvez lhe consiga apaziguar o furor acerca de vosso pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 31, 'Então voltou Moisés ao SENHOR, e disse: Rogo-te, pois este povo cometeu um grande pecado, porque fizeram para si deuses de ouro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 32, 'Que perdoes agora seu pecado, e se não, apaga-me agora de teu livro que escreveste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 33, 'E o SENHOR respondeu a Moisés: Ao que pecar contra mim, a este apagarei eu de meu livro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 34, 'Vai, pois, agora, leva a este povo aonde te disse: eis que meu anjo irá diante de ti; que no dia de minha visitação eu visitarei neles seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 32, 35, 'E o SENHOR feriu ao povo, porque fizeram o bezerro que formou Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 1, 'E o SENHOR disse a Moisés: Vai, sobe daqui, tu e o povo que tiraste da terra do Egito, à terra da qual jurei a Abraão, Isaque, e Jacó, dizendo: À tua semente a darei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 2, 'E eu enviarei diante de ti o anjo, e lançarei fora aos cananeus e aos amorreus, e aos heteus, e aos perizeus, e aos heveus e aos jebuseus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 3, '(À terra que flui leite e mel); porque eu não subirei em meio de ti, porque és povo de dura cerviz, não seja que te consuma no caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 4, 'E ouvindo o povo esta desagradável palavra, vestiram luto, e ninguém se pôs seus ornamentos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 5, 'Pois o SENHOR disse a Moisés: Dize aos filhos de Israel: Vós sois povo de dura cerviz: em um momento subirei em meio de ti, e te consumirei: tira de ti, pois, agora teus ornamentos, que eu saberei o que te tenho de fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 6, 'Então os filhos de Israel se despojaram de seus ornamentos desde o monte Horebe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 7, 'E Moisés tomou o tabernáculo, e estendeu-o fora do acampamento, longe do acampamento, e chamou-o o Tabernáculo do Testemunho. E foi que qualquer um que buscava ao SENHOR saía ao tabernáculo do testemunho, que estava fora do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 8, 'E sucedia que, quando saía Moisés ao tabernáculo, todo o povo se levantava, e estava cada qual em pé à porta de sua tenda, e olhavam por trás de Moisés, até que ele entrava no tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 9, 'E quando Moisés entrava no tabernáculo, a coluna de nuvem descia, e punha-se à porta do tabernáculo, e o SENHOR falava com Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 10, 'E vendo todo o povo a coluna de nuvem, que estava à porta do tabernáculo, levantava-se todo o povo, cada um à porta de sua tenda e adorava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 11, 'E falava o SENHOR a Moisés face a face, como fala qualquer um a seu companheiro. E voltava-se ao campo; mas o jovem Josué, seu criado, filho de Num, nunca se afastava do meio do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 12, 'E disse Moisés ao SENHOR: Olha, tu me dizes a mim: Tira este povo: e tu não me declaraste a quem hás de enviar comigo: porém, tu dizes: Eu te conheci por teu nome, e achaste também graça em meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 13, 'Agora, pois, se achei graça em teus olhos, rogo-te que me mostres agora teu caminho, para que te conheça, para que ache graça em teus olhos: e olha que teu povo é esta gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 14, 'E ele disse: Meu rosto irá contigo, e te farei descansar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 15, 'E ele respondeu: Se teu rosto não for comigo, não nos tires daqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 16, 'E em que se conhecerá aqui que achei favor em teus olhos, eu e teu povo, se não em andar tu conosco, e que eu e teu povo sejamos separados de todos os povos que estão sobre a face da terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 17, 'E o SENHOR disse a Moisés: Também farei isto que disseste, porquanto achaste favor em meus olhos, e te conheci por teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 18, 'O então disse: Rogo-te que me mostres tua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 19, 'E respondeu-lhe: Eu farei passar todo o meu bem diante de teu rosto, e proclamarei o nome do SENHOR diante de ti; e terei misericórdia do que terei misericórdia, e serei clemente para com o que serei clemente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 20, 'Disse mais: Não poderás ver meu rosto: porque não me verá homem, e viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 21, 'E disse ainda o SENHOR: Eis aqui um lugar junto a mim, e tu estarás sobre a rocha:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 22, 'E será que, quando passar minha glória, eu te porei em uma brecha da rocha, e te cobrirei com minha mão até que tenha passado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 33, 23, 'Depois tirarei minha mão, e verás minhas costas; mas não se verá meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 1, 'E o SENHOR disse a Moisés: Entalha para ti duas tábuas de pedra como as primeiras, e escreverei sobre essas tábuas as palavras que estavam nas tábuas primeiras que quebraste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 2, 'Prepara-te, pois, para amanhã, e sobe pela manhã ao monte de Sinai, e fica diante de mim ali sobre o cume do monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 3, 'E não suba homem contigo, nem apareça alguém em todo o monte; nem ovelhas nem bois apascentem diante do monte.')
